<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';
 import {EnterpriseServices} from './company-services';
 import {mcpFields,mcpError,type McpServer,type McpCapabilities} from '$lib/utils/starli-account-mcp';
 export let companyId:string;export let actorId:string;export let accessSignal:AbortSignal;
 export let initialTab:'resources'|'connections'|'tools'='resources';
 const dispatch=createEventDispatcher();let service:EnterpriseServices|null=null,mounted=false,seenCompany='',seenActor='',seenSignal:AbortSignal,detach=()=>{};
 let tab=initialTab,query='',loading=true,busy=false,error='',notice='',resourceError='',toolError='',mcpLoadError='';let resources:any[]=[],tools:any[]=[],servers:McpServer[]=[],caps:McpCapabilities|null=null,cursor='',hasMore=false;
 let oauthOptions:{version:string;supported:boolean;endpoint:string;provider:string;requiresControlPlaneAdministrator:boolean;scopes:string[]}|null=null;
 let editor:McpServer|null|undefined=undefined,name='',url='',transport:McpServer['transport']='streamable-http',credential='',clearCredential=false,removeConfirm='';
 $: filteredTools=tools.filter(t=>(t.title+' '+t.name+' '+t.description).toLowerCase().includes(query.toLowerCase()));
 const labels:Record<string,string>={'resource.file':'Drive','resource.document':'Docs and knowledge','resource.project':'Projects','resource.tasks':'Tasks','resource.sheet':'Sheets','resource.email':'Email Studio'};
 function closeEditor(){editor=undefined;name='';url='';credential='';clearCredential=false;}
 function clear(){service?.close();service=null;resources=[];tools=[];servers=[];caps=null;oauthOptions=null;cursor='';hasMore=false;closeEditor();removeConfirm='';query='';loading=false;busy=false;}
 function fail(cause:any){if(cause.name==='AbortError')return;error=cause.message||'The service is unavailable.';if(cause.status===401||cause.companyDenied){clear();dispatch('denied',{status:cause.status});}}
 async function load(){const current=service;if(!current||busy)return;loading=true;error='';resourceError='';toolError='';mcpLoadError='';try{await current.authority();const result=await Promise.allSettled([current.manifests(),current.catalog(),current.mcp().capabilities!(accessSignal),current.mcp().list('',accessSignal),current.json('/api/v1/starli/mcp/oauth/options')]);if(current!==service)return;current.current();for(const r of result)if(r.status==='rejected'&&(r.reason.companyDenied||r.reason.status===401)){fail(r.reason);return;}resources=result[0].status==='fulfilled'?result[0].value:[];tools=result[1].status==='fulfilled'?result[1].value:[];caps=result[2].status==='fulfilled'?result[2].value:null;if(result[3].status==='fulfilled'){servers=result[3].value.items;cursor=result[3].value.cursor;hasMore=result[3].value.hasMore;}else{servers=[];cursor='';hasMore=false;}oauthOptions=result[4].status==='fulfilled'&&result[4].value?.version==='starli.mcp-oauth.v1'&&result[4].value?.supported===true&&result[4].value?.endpoint==='https://api.starlidigital.ro/mcp'&&result[4].value?.requiresControlPlaneAdministrator===true&&JSON.stringify(result[4].value?.scopes)==='["read"]'?result[4].value:null;if(result[0].status==='rejected')resourceError='Company resource discovery is unavailable.';if(result[1].status==='rejected')toolError='The authenticated tool catalog is unavailable.';if(result[2].status==='rejected'||result[3].status==='rejected'){
 const c=result[2].status==='rejected'?result[2].reason:null;
 const l=result[3].status==='rejected'?result[3].reason:null;
 const codes=[c,l].map((v:any)=>typeof v?.message==='string'?v.message:'');
 mcpLoadError=codes.includes('MCP_AUTH_REQUIRED')?'The MCP session is no longer authorized. Sign out and sign in to StarliApp again, then refresh Connections.':
  codes.includes('MCP_RESPONSE_INVALID')?'The MCP service returned an unexpected response. Refresh Connections; if this continues, report MCP_RESPONSE_INVALID.':
  codes.includes('MCP_SERVICE_UNAVAILABLE')?'The MCP management API could not complete the request. Refresh, then check the backend service if it persists.':
  codes.includes('MCP_TRANSPORT_UNAVAILABLE')?'The isolated MCP transport is temporarily unavailable. Saved connections remain intact.':
  'Account MCP management failed to load. Refresh Connections. If it persists, check your signed-in session and the MCP API status.';
}}catch(e){if(current===service)fail(e);}finally{if(current===service)loading=false;}}
 function edit(row:McpServer|null){editor=row;name=row?.name||'';url=row?.url||'';transport=row?.transport||'streamable-http';credential='';clearCredential=false;error='';notice='';removeConfirm='';}
 async function mutation(fn:(api:ReturnType<EnterpriseServices['mcp']>)=>Promise<any>,message:string,after?:(value:any)=>void){const current=service;if(!current||busy)return;busy=true;error='';notice='';try{await current.authority();const value=await fn(current.mcp());if(current!==service)return;current.current();if(value?.version==='starli.account-mcp.v1')servers=[...servers.filter(s=>s.id!==value.id),value].sort((a,b)=>a.name.localeCompare(b.name));after?.(value);notice=message;}catch(e){if(current===service){if((e as any).companyDenied||(e as any).status===401)fail(e);else error=mcpError(e);}}finally{if(current===service)busy=false;}}
 async function save(){let fields;try{fields=mcpFields(name,url,transport,credential,clearCredential);}catch(e){error=mcpError(e);credential='';return;}credential='';const selected=editor;await mutation(api=>selected?api.update(selected.id,{...fields,expectedRevision:selected.revision},accessSignal):api.create(fields,accessSignal),'Connection saved. Test and discover before using its tools.',closeEditor);}
 const oauthEndpoint='https://api.starlidigital.ro/mcp';
 function oauthEligible(row:McpServer){return oauthOptions?.supported===true&&row.url===oauthEndpoint&&row.transport==='streamable-http';}
 function oauthPopup():Window|null{
  const pop=window.open('about:blank','_blank','popup,width=540,height=730');
  if(!pop)error='Allow the Starli Control Plane sign-in window in your browser, then try again.';
  return pop;
 }
 async function startOauth(row:McpServer,pop:Window,current:EnterpriseServices){
  const data=await current.json('/api/v1/starli/mcp/oauth/start',{method:'POST',body:JSON.stringify({serverId:row.id,expectedRevision:row.revision})});
  current.current();
  const link=new URL(String(data.authorizationUrl||''));
  const returnUrl=location.origin+'/api/v1/starli/mcp/oauth/callback';
  if(data.version!=='starli.mcp-oauth.v1'||data.scope!=='read'||data.issuer!=='https://api.starlidigital.ro'||link.origin!=='https://api.starlidigital.ro'||link.pathname!=='/oauth/authorize'||link.searchParams.get('redirect_uri')!==returnUrl||link.searchParams.get('scope')!=='read')
   throw Error('MCP_OAUTH_AUTHORIZATION_UNVERIFIED');
  pop.location.assign(link.href);
  notice='Complete the separate Starli Control Plane administrator sign-in. Afterwards return here and click Refresh to test and discover tools. No access is granted to a bot automatically.';
 }
 async function signIn(row:McpServer){
  if(busy||!oauthEligible(row)||!service)return;
  const pop=oauthPopup();if(!pop)return;
  const current=service;busy=true;error='';notice='';
  try{await current.authority();await startOauth(row,pop,current);}
  catch(cause){pop.close();if(current===service)error=mcpError(cause);}
  finally{if(current===service)busy=false;}
 }
 async function saveAndSignIn(){
  if(busy||!service||!oauthOptions?.supported||url!==oauthEndpoint||transport!=='streamable-http'||credential.trim())return;
  const pop=oauthPopup();if(!pop)return;
  let fields;try{fields=mcpFields(name,url,transport,'',clearCredential);}catch(e){pop.close();error=mcpError(e);return;}
  const current=service,selected=editor;busy=true;error='';notice='';
  try{
   await current.authority();
   const saved=selected?await current.mcp().update(selected.id,{...fields,expectedRevision:selected.revision},accessSignal):await current.mcp().create(fields,accessSignal);
   current.current();
   if(saved.url!==oauthEndpoint||!/^mcp_[a-f0-9]{32}$/.test(saved.id))throw Error('MCP_RESPONSE_INVALID');
   servers=[...servers.filter(s=>s.id!==saved.id),saved].sort((a,b)=>a.name.localeCompare(b.name));
   closeEditor();
   await startOauth(saved,pop,current);
  }catch(cause){pop.close();if(current===service)error=mcpError(cause);}
  finally{if(current===service){busy=false;void load();}}
 }
 function oauthFocus(){if(service&&tab==='connections'&&!busy)void load();}
function enable(row:McpServer){void mutation(api=>api.enable(row.id,row.revision,!row.enabled,accessSignal),'Connection setting updated for your account.');}
 function test(row:McpServer){void mutation(api=>api.test!(row.id,row.revision,accessSignal),'Connection test succeeded.');}
 function discover(row:McpServer){void mutation(api=>api.discover!(row.id,row.revision,accessSignal),'Tool discovery completed.');}
 function remove(row:McpServer){void mutation(api=>api.remove(row.id,row.revision,accessSignal),'Connection removed from your account.',()=>{servers=servers.filter(s=>s.id!==row.id);removeConfirm='';if(editor?.id===row.id)closeEditor();});}
 async function more(){const current=service;if(!current||busy||!hasMore)return;busy=true;try{await current.authority();const page=await current.mcp().list(cursor,accessSignal);if(current!==service)return;current.current();servers=[...new Map([...servers,...page.items].map(s=>[s.id,s])).values()];cursor=page.cursor;hasMore=page.hasMore;}catch(e){if(current===service)fail(e);}finally{if(current===service)busy=false;}}
 function use(tool:any){try{service?.current();if(service&&(tool.executable||tool.approval))dispatch('tool',{toolName:tool.name,title:tool.title,approvalAvailable:tool.approval});}catch(e){fail(e);}}
 function openResource(row:any){try{service?.current();if(service)dispatch('resource',{type:row.type,kinds:row.resourceKinds});}catch(e){fail(e);}}
 function start(){detach();clear();tab=initialTab;seenCompany=companyId;seenActor=actorId;seenSignal=accessSignal;service=new EnterpriseServices(companyId,actorId,accessSignal);const parent=accessSignal;const lost=()=>clear();parent.addEventListener('abort',lost,{once:true});detach=()=>parent.removeEventListener('abort',lost);void load();}
 function session(e:StorageEvent){if(e.key==='token'||e.key===null){clear();error='Your session changed. Reopen Apps.';dispatch('denied',{status:401});}}
 $: if(mounted&&(companyId!==seenCompany||actorId!==seenActor||accessSignal!==seenSignal))start();
 onMount(()=>{mounted=true;window.addEventListener('focus',oauthFocus);return()=>window.removeEventListener('focus',oauthFocus);});onDestroy(()=>{mounted=false;detach();clear();});
</script>
<svelte:window on:storage={session}/>
<section class="apps"><header><div><h2>Apps</h2><p>Connections, resources and tools for your work.</p></div><button class="refresh" disabled={loading||busy} on:click={load}>Refresh</button></header><nav aria-label="Apps sections">{#each [['resources','Company resources'],['connections','Connections'],['tools','Tools in chat']] as [id,label]}<button class:active={tab===id} on:click={()=>{tab=id;error='';notice='';}}>{label}</button>{/each}</nav>
{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="notice" role="status">{notice}</p>{/if}
{#if loading}<p class="empty" role="status">Loading available apps and connections…</p>
{:else if tab==='resources'}<div class="section-heading"><div><h3>Company resources</h3><p>Registered resource types. Select one to browse authorized company records.</p></div></div>{#if resourceError}<p class="error">{resourceError}</p>{/if}<div class="grid">{#each resources as row(row.type)}<button class="resource card" on:click={()=>openResource(row)}><span class="icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><rect x="4" y="4" width="16" height="16" rx="3"/><path d="M4 10h16M10 10v10"/></svg></span><strong>{labels[row.type]||row.title}</strong><p>{row.resourceKinds.join(' · ')}</p><footer><span>Registered</span><span>Open ↗</span></footer></button>{:else}<p class="empty">No company resource types could be verified.</p>{/each}</div>
{:else if tab==='tools'}<div class="section-heading"><div><h3>Use tools through chat</h3><p>This catalog follows your signed-in account’s grants. It is not a list of company-owned connections.</p></div><span class="count">{tools.length} tools</span></div>{#if toolError}<p class="error">{toolError}</p>{/if}<input class="search" aria-label="Search available tools" placeholder="Search tools…" bind:value={query}/><div class="tools">{#each filteredTools as tool(tool.name)}<article><div><strong>{tool.title}</strong><small>{tool.name}</small><p>{tool.description}</p></div><button disabled={!tool.executable&&!tool.approval} on:click={()=>use(tool)}>{tool.executable?'Use in chat':tool.approval?'Request in chat':'Requires access'}</button></article>{:else}<p class="empty">No matching tools in the authenticated catalog.</p>{/each}</div>
{:else}<div class="section-heading"><div><h3>Your account MCP connections</h3><p>These MCP servers belong to your signed-in account, not the company vault. Approved company bots can use selected discovered tools for their next task only after explicit consent from the owner in that bot's chat. Do not enter an unrestricted server administrator token.</p></div><button class="primary" disabled={!caps||busy} on:click={()=>edit(null)}>Add MCP server</button></div>{#if mcpLoadError}<p class="error">{mcpLoadError}</p>{/if}{#if caps&&!caps.transports['streamable-http']&&!caps.transports.sse}<p class="transport-note" role="status">Remote MCP transport is unavailable on this server. You can save connection settings; testing, discovery and enabling are unavailable.</p>{/if}<p class="hint">Secure HTTPS connections · Streamable HTTP or SSE. A Starli Control Plane sign-in requires a separate administrator account, not your StarliApp company login. It requests read-only access; Test, Discover, Enable and explicit bot consent remain separate. Other servers require a manually issued Bearer token until reviewed OAuth support is added.</p>
{#if editor!==undefined}<form class="editor" on:submit|preventDefault={save}><h3>{editor?'Edit MCP connection':'Add MCP connection'}</h3><div class="form-grid"><label>Name<input maxlength="100" bind:value={name} required disabled={busy}/></label><label>Transport<select bind:value={transport} disabled={busy}><option value="streamable-http">Streamable HTTP</option><option value="sse">SSE</option></select></label></div><label>HTTPS endpoint<input type="url" bind:value={url} placeholder="https://example.com/mcp" required disabled={busy}/></label><label>Bearer credential · optional<input type="password" autocomplete="new-password" bind:value={credential} maxlength="8192" disabled={busy||clearCredential}/></label>{#if editor?.credentialConfigured}<p class="hint">A credential is already configured. Leave blank to keep it. Stored credentials are never displayed.</p><label class="check"><input type="checkbox" bind:checked={clearCredential} disabled={busy}/> Remove saved credential</label>{/if}<div class="actions">{#if editor}<button type="button" disabled={busy} on:click={()=>{const fresh=servers.find(s=>s.id===editor?.id);if(fresh)edit(fresh);}}>Reload saved version</button>{/if}<button type="button" disabled={busy} on:click={closeEditor}>Cancel</button>{#if oauthOptions?.supported&&url===oauthEndpoint&&transport==='streamable-http'&&!credential}<button type="button" class="primary" disabled={busy||!name.trim()} on:click={()=>void saveAndSignIn()}>Save & sign in (read only)</button>{/if}<button class="primary" disabled={busy}>{busy?'Saving…':'Save connection'}</button></div></form>{/if}
<div class="connections">{#each servers as row(row.id)}<article class="connection"><div class="connection-top"><span class="icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m9 8 6 8M8 4l-4 4 4 4M16 12l4 4-4 4"/></svg></span><div><strong>{row.name}</strong><small>{row.url}</small></div><span class="badge" class:enabled={row.enabled}>{row.enabled?'Enabled':'Disabled'}</span></div><p>{row.transport==='sse'?'SSE':'Streamable HTTP'} · {row.toolCount} tools · {row.status==='DISCOVERED'?'Discovered':'Not tested'} · Revision {row.revision}</p><div class="connection-actions">{#if oauthEligible(row)}<button disabled={busy} on:click={()=>void signIn(row)}>Sign in (read only)</button>{/if}<button disabled={busy} on:click={()=>edit(row)}>Edit</button><button disabled={busy||!caps?.transports[row.transport]} on:click={()=>test(row)}>Test</button><button disabled={busy||!caps?.transports[row.transport]} on:click={()=>discover(row)}>Discover tools</button><button disabled={busy||(!row.enabled&&!caps?.transports[row.transport])} on:click={()=>enable(row)}>{row.enabled?'Disable':'Enable'}</button><button class="danger" disabled={busy} on:click={()=>removeConfirm=row.id}>Remove</button></div>{#if removeConfirm===row.id}<div class="confirm"><span>Remove this connection for all your owned bots?</span><button disabled={busy} on:click={()=>removeConfirm=''}>Cancel</button><button class="danger" disabled={busy} on:click={()=>remove(row)}>Confirm removal</button></div>{/if}</article>{:else}<p class="empty">No account MCP connections are loaded.</p>{/each}</div>{#if hasMore}<button class="refresh" disabled={busy} on:click={more}>Load more connections</button>{/if}{/if}</section>
<style>.apps{width:100%;max-width:1180px;margin:auto;padding:36px 42px;color:#17243f;height:100%;overflow:auto}header,.section-heading{display:flex;align-items:center;justify-content:space-between;gap:20px}h2{font-size:25px;font-weight:550;letter-spacing:-.7px;margin:0}header p,.section-heading p{font-size:12px;color:#8b96aa;margin-top:7px;line-height:1.7}.section-heading{align-items:flex-start;margin:26px 0 16px}.section-heading h3{font-size:14px;font-weight:550;margin:0}.section-heading p{max-width:650px;font-size:11px}button,input,select{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:default}.primary{border:0;border-radius:8px;padding:9px 14px;background:#3466f6;color:white;font-size:12px;white-space:nowrap}.refresh,.actions>button:not(.primary){background:none;border:0;color:#7f8fa9;font-size:11px;padding:8px}nav{display:flex;gap:22px;margin-top:26px;border-bottom:1px solid #e6ebf4}nav button{background:none;border:0;border-bottom:2px solid transparent;padding:10px 0 13px;color:#98a3b6;font-size:12px}nav button.active{border-color:#3466f6;color:#3466f6}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.card{background:white;border:1px solid #e6ebf4;border-radius:12px;min-height:195px;padding:22px;display:flex;flex-direction:column;align-items:flex-start;text-align:left;color:inherit}.card:hover{border-color:#afc2fb;box-shadow:0 4px 20px #3466f609}.icon{width:38px;height:38px;display:grid;place-items:center;background:#eef3ff;border-radius:9px;color:#6f8fd6;flex:none}.icon svg{width:21px;height:21px}.card strong{font-size:14px;font-weight:550;margin-top:19px}.card p{color:#98a3b5;font-size:11px;margin:7px 0 20px}.card footer{display:flex;justify-content:space-between;width:100%;border-top:1px solid #eef1f6;margin-top:auto;padding-top:12px;font-size:10px;color:#a0aabd}.empty{grid-column:1/-1;text-align:center;padding:40px 15px;color:#9ca7b9;font-size:12px}.count,.badge{font-size:10px;background:#f6f8fc;color:#99a6ba;border:1px solid #e6ebf4;padding:4px 8px;border-radius:5px;white-space:nowrap}.search{border:1px solid #e6ebf4;background:#f6f8fc;border-radius:8px;padding:10px 13px;font-size:12px;width:min(360px,100%);margin:0 0 15px}.tools{border-top:1px solid #e6ebf4}.tools article{display:flex;align-items:center;justify-content:space-between;gap:24px;border-bottom:1px solid #e6ebf4;padding:18px 0}.tools strong,.connection strong{font-size:12px;font-weight:550;display:block}.tools small,.connection small{font-size:10px;color:#a0aabc;display:block;margin-top:3px;overflow-wrap:anywhere}.tools p{font-size:11px;color:#97a2b5;line-height:1.7;max-width:700px;margin-top:7px}.tools article>button{flex:none;border:1px solid #e6ebf4;border-radius:7px;background:white;color:#7c91b4;font-size:11px;padding:8px 10px}.hint{font-size:10px;line-height:1.7;color:#a1aabc;margin:12px 0 20px}.editor{background:#f9fbff;border:1px solid #e1e8f6;border-radius:12px;padding:22px;margin:20px 0}.editor h3{font-size:14px;font-weight:550;margin:0 0 17px}.editor label{display:flex;flex-direction:column;gap:6px;font-size:11px;color:#7b8ba3;margin:12px 0}.editor input,.editor select{border:1px solid #e1e7f2;border-radius:7px;background:white;padding:9px 11px;color:#17243f;width:100%;font-size:12px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:16px}.editor label.check{flex-direction:row;align-items:center}.check input{width:auto}.connections{display:flex;flex-direction:column;gap:14px}.connection{border:1px solid #e6ebf4;border-radius:12px;padding:20px}.connection-top{display:flex;align-items:center;gap:12px}.connection-top>div{min-width:0}.connection-top .badge{margin-left:auto}.badge.enabled{color:#6586c5;background:#f0f5ff;border-color:#e2ebff}.connection>p{font-size:10px;color:#a1aabc;margin:13px 0}.connection-actions{display:flex;gap:16px;flex-wrap:wrap}.connection-actions button,.confirm button{background:none;border:0;padding:4px 0;color:#8194b3;font-size:11px}.danger{color:#ac6670!important}.confirm{display:flex;gap:14px;align-items:center;background:#fff7f8;border-radius:7px;padding:10px 12px;margin-top:14px;font-size:11px;color:#a56870}.confirm span{margin-right:auto}.error{font-size:12px;line-height:1.7;color:#ad4b52;overflow-wrap:anywhere}.notice{font-size:12px;color:#638b79;background:#f3faf6;padding:10px 13px;border-radius:8px;margin-top:18px}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #789bff;outline-offset:3px}@media(max-width:1150px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.apps{padding:26px 22px}.grid{grid-template-columns:1fr}h2{font-size:23px}header{align-items:flex-start}nav{gap:18px;overflow-x:auto;white-space:nowrap}nav button{font-size:11px}.section-heading{flex-wrap:wrap}.form-grid{grid-template-columns:1fr;gap:0}.tools article{align-items:flex-start;gap:10px}.tools article>button{font-size:10px}.connection-actions{gap:14px}.confirm{flex-wrap:wrap}}.transport-note{font-size:11px;color:#a18a58;background:#fcf9f1;border:1px solid #f0e9d9;border-radius:8px;padding:12px 14px;line-height:1.7}</style>
